import 'package:flutter/material.dart';
import '../services/notifications_service.dart';

class NotificationsPage extends StatefulWidget { const NotificationsPage({super.key}); @override State<NotificationsPage> createState()=>_NotificationsPageState(); }
class _NotificationsPageState extends State<NotificationsPage>{ final service=NotificationsService(); List<HadirNotification> rows=[]; @override void initState(){super.initState();_load();} Future<void> _load()async{final r=await service.list();if(mounted)setState(()=>rows=r);} @override Widget build(BuildContext context){final unread=rows.where((e)=>!e.read).length;return Scaffold(appBar:AppBar(title:Text('الإشعارات${unread>0?' ($unread)':''}'),actions:[if(unread>0)IconButton(onPressed:()async{await service.markAllRead();_load();},icon:const Icon(Icons.done_all),tooltip:'تحديد الكل كمقروء')]),body:rows.isEmpty?const Center(child:Text('لا توجد إشعارات')):ListView.separated(padding:const EdgeInsets.all(12),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:6),itemBuilder:(c,i){final n=rows[i];return Card(child:ListTile(onTap:()async{if(!n.read)await service.markRead(n.id);_load();},leading:CircleAvatar(child:Icon(n.read?Icons.notifications_none:Icons.notifications_active)),title:Text(n.title,style:TextStyle(fontWeight:n.read?FontWeight.normal:FontWeight.bold)),subtitle:Text('${n.body}\n${n.createdAt.toLocal()}'),isThreeLine:true));}));}}
